    content: "#include \"Core/Timer.hpp\"\n\nnamespace NeonCity::Core\n{\n    Timer::Timer()\n    {\n        __int64 countsPerSec;\n        QueryPerformanceFrequency(reinterpret_cast<LARGE_INTEGER*>(&countsPerSec));\n        m_secondsPerCount = 1.0 / static_cast<double>(countsPerSec);\n\n        __int64 currTime;\n        QueryPerformanceCounter(reinterpret_cast<LARGE_INTEGER*>(&currTime));\n        m_baseTime = currTime;\n        m_prevTime = currTime;\n    }\n\n    void Timer::Reset()\n    {\n        __int64 currTime;\n        QueryPerformanceCounter(reinterpret_cast<LARGE_INTEGER*>(&currTime));\n        m_baseTime = currTime;\n        m_prevTime = currTime;\n        m_stopTime = 0;\n        m_pausedTime = 0;\n        m_isStopped = false;\n    }\n\n    void Timer::Start()\n    {\n        __int64 startTime;\n        QueryPerformanceCounter(reinterpret_cast<LARGE_INTEGER*>(&startTime));\n\n        if (m_isStopped)\n        {\n            m_pausedTime += (startTime - m_stopTime);\n            m_prevTime = startTime;\n            m_stopTime = 0;\n            m_isStopped = false;\n        }\n    }\n\n    void Timer::Stop()\n    {\n        if (!m_isStopped)\n        {\n            __int64 currTime;\n            QueryPerformanceCounter(reinterpret_cast<LARGE_INTEGER*>(&currTime));\n            m_stopTime = currTime;\n            m_isStopped = true;\n        }\n    }\n\n    void Timer::Tick()\n    {\n        if (m_isStopped)\n        {\n            m_deltaTime = 0.0;\n            return;\n        }\n\n        __int64 currTime;\n        QueryPerformanceCounter(reinterpret_cast<LARGE_INTEGER*>(&currTime));\n        m_currTime = currTime;\n\n        m_deltaTime = (m_currTime - m_prevTime) * m_secondsPerCount;\n        m_prevTime = m_currTime;\n\n        // Prevent negative delta time from processor frequency throttling\n        if (m_deltaTime < 0.0)\n        {\n            m_deltaTime = 0.0;\n        }\n\n        // FPS calculation update\n        m_frameCount++;\n        m_fpsTimeElapsed += static_cast<float>(m_deltaTime);\n        if (m_fpsTimeElapsed >= 1.0f)\n        {\n            m_fps = m_frameCount;\n            m_frameCount = 0;\n            m_fpsTimeElapsed -= 1.0f;\n        }\n    }\n\n    float Timer::GetTotalTime() const\n    {\n        if (m_isStopped)\n        {\n            return static_cast<float>(((m_stopTime - m_pausedTime) - m_baseTime) * m_secondsPerCount);\n        }\n        else\n        {\n            return static_cast<float>(((m_currTime - m_pausedTime) - m_baseTime) * m_secondsPerCount);\n        }\n    }\n}\n"
